  1→using System.Security.Claims;
  2→using System.Text.Encodings.Web;
  3→using System.Text.Json;
  4→using dotenv.net;
  5→using Microsoft.AspNetCore.Authentication;
  6→using Microsoft.AspNetCore.Authentication.JwtBearer;
  7→using Microsoft.EntityFrameworkCore;
  8→using Microsoft.Extensions.FileProviders;
  9→using Microsoft.Extensions.Options;
 10→using Microsoft.IdentityModel.Tokens;
 11→using OmgtuPortal;
 12→using OmgtuPortal.Data;
 13→using OmgtuPortal.University;
 14→using Scalar.AspNetCore;
 15→
 16→DotEnv.Load();
 17→
 18→var appSettings = AppSettings.FromEnvironment();
 19→
 20→var builder = WebApplication.CreateBuilder(args);
 21→
 22→builder.Services.AddSingleton(appSettings);
 23→builder.Services.AddOpenApi();
 24→
 25→// Database
 26→builder.Services.AddDbContext<AppDbContext>(options =>
 27→{
 28→    if (builder.Environment.IsDevelopment())
 29→        options.UseSqlite("Data Source=app.db");
 30→    else
 31→        options.UseNpgsql(appSettings.DatabaseUrl);
 32→});
 33→
 34→// CORS
 35→builder.Services.AddCors(options =>
 36→{
 37→    options.AddDefaultPolicy(policy =>
 38→    {
 39→        var origins = appSettings.CorsOrigins
 40→            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
 41→
 42→        policy.WithOrigins(origins)
 43→              .AllowAnyHeader()
 44→              .AllowAnyMethod()
 45→              .AllowCredentials();
 46→    });
 47→});
 48→
 49→// Authentication
 50→if (appSettings.AutoLogin && builder.Environment.IsDevelopment())
 51→{
 52→    builder.Services.AddAuthentication("DevAutoLogin")
 53→        .AddScheme<AuthenticationSchemeOptions, DevAutoLoginHandler>("DevAutoLogin", null);
 54→}
 55→else
 56→{
 57→    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
 58→        .AddJwtBearer(options =>
 59→        {
 60→            options.Authority = appSettings.Authority;
 61→            options.Audience = appSettings.KeycloakClientId;
 62→            options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
 63→
 64→            options.TokenValidationParameters = new TokenValidationParameters
 65→            {
 66→                ValidateIssuer = true,
 67→                ValidIssuer = appSettings.Authority,
 68→                ValidateAudience = true,
 69→                ValidAudience = appSettings.KeycloakClientId,
 70→                ValidateLifetime = true,
 71→            };
 72→
 73→            options.Events = new JwtBearerEvents
 74→            {
 75→                OnTokenValidated = context =>
 76→                {
 77→                    if (context.Principal?.Identity is not ClaimsIdentity identity)
 78→                        return Task.CompletedTask;
 79→
 80→                    var realmAccess = identity.FindFirst("realm_access")?.Value;
 81→                    if (realmAccess is null)
 82→                        return Task.CompletedTask;
 83→
 84→                    try
 85→                    {
 86→                        using var doc = JsonDocument.Parse(realmAccess);
 87→                        if (doc.RootElement.TryGetProperty("roles", out var roles))
 88→                        {
 89→                            foreach (var role in roles.EnumerateArray())
 90→                            {
 91→                                var value = role.GetString();
 92→                                if (!string.IsNullOrEmpty(value))
 93→                                    identity.AddClaim(new Claim(ClaimTypes.Role, value));
 94→                            }
 95→                        }
 96→                    }
 97→                    catch (JsonException)
 98→                    {
 99→                        // Ignore malformed claim
100→                    }
101→
102→                    return Task.CompletedTask;
103→                }
104→            };
105→        });
106→}
107→
108→builder.Services.AddAuthorization();
109→builder.Services.AddControllers();
110→
111→// University client
112→switch (appSettings.UniversityProvider?.ToLowerInvariant())
113→{
114→    case "local" or null or "":
115→        builder.Services.AddSingleton<IUniversityClient, LocalUniversityClient>();
116→        break;
117→    case "http":
118→        if (string.IsNullOrWhiteSpace(appSettings.UniversityBaseUrl))
119→            throw new InvalidOperationException(
120→                "UNIVERSITY_BASE_URL is required when UNIVERSITY_PROVIDER=http");
121→        builder.Services.AddHttpClient<IUniversityClient, HttpUniversityClient>(client =>
122→        {
123→            client.BaseAddress = new Uri(appSettings.UniversityBaseUrl);
124→            client.Timeout = TimeSpan.FromSeconds(10);
125→        });
126→        break;
127→    default:
128→        throw new InvalidOperationException(
129→            $"Unknown UNIVERSITY_PROVIDER '{appSettings.UniversityProvider}'. Supported values: local, http");
130→}
131→
132→var app = builder.Build();
133→
134→// Auto-apply migrations
135→using (var scope = app.Services.CreateScope())
136→{
137→    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
138→    db.Database.Migrate();
139→}
140→
141→if (app.Environment.IsDevelopment())
142→{
143→    app.MapOpenApi();
144→    app.MapScalarApiReference("/docs");
145→}
146→
147→app.UseCors();
148→app.UseAuthentication();
149→app.UseAuthorization();
150→
151→app.UseStaticFiles(new StaticFileOptions
152→{
153→    FileProvider = new PhysicalFileProvider(
154→        Path.Combine(builder.Environment.ContentRootPath, ".frontend", "dist")),
155→    RequestPath = ""
156→});
157→
158→app.MapControllers();
159→
160→// Endpoints
161→
162→app.MapGet("/api/health", () => Results.Ok(new { Status = "Healthy" }))
163→    .Produces<object>(StatusCodes.Status200OK);
164→
165→app.MapGet("/api/me", (ClaimsPrincipal user) => Results.Ok(new
166→    {
167→        Sub = user.FindFirstValue(ClaimTypes.NameIdentifier) ?? user.FindFirstValue("sub"),
168→        PreferredUsername = user.FindFirstValue("preferred_username"),
169→        Email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue("email"),
170→        GivenName = user.FindFirstValue(ClaimTypes.GivenName) ?? user.FindFirstValue("given_name"),
171→        FamilyName = user.FindFirstValue(ClaimTypes.Surname) ?? user.FindFirstValue("family_name"),
172→        Roles = user.FindAll(ClaimTypes.Role).Select(c => c.Value).ToList(),
173→    }))
174→    .RequireAuthorization()
175→    .Produces<object>(StatusCodes.Status200OK)
176→    .Produces(StatusCodes.Status401Unauthorized);
177→
178→// SPA fallback
179→
180→app.MapFallback(async context =>
181→{
182→    if (context.Request.Path.StartsWithSegments("/api"))
183→    {
184→        context.Response.StatusCode = 404;
185→        await context.Response.WriteAsJsonAsync(new { Error = "Not Found" });
186→        return;
187→    }
188→
189→    var indexPath = Path.Combine(builder.Environment.ContentRootPath, ".frontend", "dist", "index.html");
190→    context.Response.ContentType = "text/html";
191→    await context.Response.SendFileAsync(indexPath);
192→});
193→
194→app.Run();
195→
196→// Dev-only auth handler: auto-authenticates every request with all roles
197→sealed class DevAutoLoginHandler(
198→    IOptionsMonitor<AuthenticationSchemeOptions> options,
199→    ILoggerFactory logger,
200→    UrlEncoder encoder)
201→    : AuthenticationHandler<AuthenticationSchemeOptions>(options, logger, encoder)
202→{
203→    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
204→    {
205→        var claims = new List<Claim>
206→        {
207→            new(ClaimTypes.NameIdentifier, "dev-user-id"),
208→            new("sub", "dev-user-id"),
209→            new("preferred_username", "developer"),
210→            new(ClaimTypes.Email, "dev@localhost"),
211→            new("email", "dev@localhost"),
212→            new(ClaimTypes.GivenName, "Dev"),
213→            new("given_name", "Dev"),
214→            new(ClaimTypes.Surname, "User"),
215→            new("family_name", "User"),
216→            new(ClaimTypes.Role, "admin"),
217→            new(ClaimTypes.Role, "user"),
218→            new(ClaimTypes.Role, "student"),
219→            new(ClaimTypes.Role, "teacher"),
220→        };
221→
222→        var identity = new ClaimsIdentity(claims, Scheme.Name);
223→        var principal = new ClaimsPrincipal(identity);
224→        var ticket = new AuthenticationTicket(principal, Scheme.Name);
225→
226→        return Task.FromResult(AuthenticateResult.Success(ticket));
227→    }
228→}
