 1→import Keycloak from 'keycloak-js'
 2→
 3→const keycloak = new Keycloak({
 4→  url: import.meta.env.VITE_KEYCLOAK_URL || 'http://localhost:8080',
 5→  realm: import.meta.env.VITE_KEYCLOAK_REALM || 'upomgtu',
 6→  clientId: import.meta.env.VITE_KEYCLOAK_CLIENT_ID || 'upomgtu',
 7→})
 8→
 9→export async function initAuth(): Promise<boolean> {
10→  let authenticated = false
11→  try {
12→    authenticated = await keycloak.init({
13→      onLoad: 'login-required',
14→      checkLoginIframe: false,
15→      responseMode: 'query',
16→    })
17→  } finally {
18→    // Clean any leftover Keycloak params from URL
19→    const url = new URL(window.location.href)
20→    const keycloakParams = ['state', 'session_state', 'code', 'iss']
21→    keycloakParams.forEach((p) => url.searchParams.delete(p))
22→    url.hash = ''
23→    window.history.replaceState(null, '', url.pathname + url.search)
24→  }
25→
26→  if (authenticated) {
27→    // Auto-refresh token before it expires
28→    setInterval(async () => {
29→      try {
30→        await keycloak.updateToken(30)
31→      } catch {
32→        keycloak.login()
33→      }
34→    }, 10_000)
35→  }
36→
37→  return authenticated
38→}
39→
40→export function getToken(): string | undefined {
41→  return keycloak.token
42→}
43→
44→export function logout(): void {
45→  keycloak.logout({ redirectUri: window.location.origin })
46→}
47→
48→export function getUserRoles(): string[] {
49→  return keycloak.realmAccess?.roles ?? []
50→}
51→
52→export { keycloak }
