import Keycloak from 'keycloak-js'

const isAutoLogin = import.meta.env.VITE_AUTOLOGIN === 'true'
const ALL_ROLES = ['admin', 'user', 'student', 'teacher']

let keycloak: Keycloak | null = null

function getKeycloak(): Keycloak {
  if (!keycloak) {
    keycloak = new Keycloak({
      url: import.meta.env.VITE_KEYCLOAK_URL || 'http://localhost:8080',
      realm: import.meta.env.VITE_KEYCLOAK_REALM || 'upomgtu',
      clientId: import.meta.env.VITE_KEYCLOAK_CLIENT_ID || 'upomgtu',
    })
  }
  return keycloak
}

export async function initAuth(): Promise<boolean> {
  if (isAutoLogin) return true

  const kc = getKeycloak()
  let authenticated = false
  try {
    authenticated = await kc.init({
      onLoad: 'login-required',
      checkLoginIframe: false,
      responseMode: 'query',
    })
  } finally {
    const url = new URL(window.location.href)
    const keycloakParams = ['state', 'session_state', 'code', 'iss']
    keycloakParams.forEach((p) => url.searchParams.delete(p))
    url.hash = ''
    window.history.replaceState(null, '', url.pathname + url.search)
  }

  if (authenticated) {
    setInterval(async () => {
      try {
        await kc.updateToken(30)
      } catch {
        kc.login()
      }
    }, 10_000)
  }

  return authenticated
}

export function getToken(): string | undefined {
  if (isAutoLogin) return undefined
  return keycloak?.token
}

export function logout(): void {
  if (isAutoLogin) {
    window.location.reload()
    return
  }
  keycloak?.logout({ redirectUri: window.location.origin })
}

export function getUserRoles(): string[] {
  if (isAutoLogin) return ALL_ROLES
  return keycloak?.realmAccess?.roles ?? []
}

